<template><div class="app-container ps-page"><h2>知识库邀请资格</h2><el-alert title="邀请码只授予知识库业务资格与初始额度，平台账号注册和登录仍由若依处理。" type="info" :closable="false" class="ps-section"/><el-alert v-if="error||pageError" :title="error||pageError" type="error" :closable="false"/><div class="ps-toolbar"><el-button v-hasPermi="['paismart:invite:manage']" type="primary" @click="edit()">创建邀请码</el-button><el-button v-hasPermi="['paismart:invite:manage']" @click="edit(undefined,true)">批量生成</el-button><el-button @click="load()">刷新</el-button><el-button :disabled="!selected.length" @click="copyInvites(selected,'codes')">复制所选邀请码</el-button><el-button :disabled="!selected.length" @click="copyInvites(selected,'links')">复制所选注册入口</el-button><el-button v-hasPermi="['paismart:invite:manage']" :disabled="!selected.length||saving" @click="bulk(false)">批量停用</el-button><el-button v-hasPermi="['paismart:invite:manage']" :disabled="!selected.length||saving" type="danger" @click="bulk(true)">批量删除</el-button></div><el-form inline><el-form-item label="启用状态"><el-select v-model="query.enabled" clearable><el-option label="可使用" :value="true"/><el-option label="已禁用" :value="false"/></el-select></el-form-item><el-button @click="load(true)">查询</el-button><el-button @click="query.enabled=undefined;load(true)">重置</el-button></el-form><el-table :data="rows" v-loading="loading" @selection-change="selected=$event"><el-table-column type="selection" width="50"/><el-table-column prop="code" label="邀请码" min-width="220"/><el-table-column label="绑定空间" min-width="170"><template #default="{row}">{{spaces.find(s=>String(s.id)===String(row.spaceId))?.name||'未绑定'}}</template></el-table-column><el-table-column label="消费次数" width="130"><template #default="{row}">{{row.usedCount}} / {{row.maxUses}}</template></el-table-column><el-table-column label="到期时间" min-width="180"><template #default="{row}">{{row.expiresAt||'永久有效'}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}">{{row.enabled?'可使用':'已禁用'}}</template></el-table-column><el-table-column label="操作" min-width="420"><template #default="{row}"><el-button link @click="copyInvites([row],'codes')">复制邀请码</el-button><el-button link @click="registrationLink(row)">复制注册入口</el-button><el-button link @click="copyInvites([row],'words')">复制分享文案</el-button><el-button v-hasPermi="['paismart:invite:manage']" link @click="edit(row)">编辑</el-button><el-button v-hasPermi="['paismart:invite:manage']" link @click="toggle(row)">{{row.enabled?'禁用':'启用'}}</el-button><el-button v-hasPermi="['paismart:invite:manage']" link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="query.pageNum" :page-size="query.pageSize" :total="total" layout="total,prev,pager,next" @current-change="load()"/><el-dialog v-model="open" :title="batch?'批量生成邀请码':form.id?'编辑邀请码':'创建邀请码'" width="650px"><el-form label-width="130px"><el-form-item v-if="batch" label="生成数量"><el-input-number v-model="count" :min="1" :max="100" :precision="0"/></el-form-item><el-form-item v-else label="邀请码"><el-input v-model="form.code" :disabled="!!form.id&&(form.usedCount??0)>0" placeholder="留空由服务端生成；未消费可修改" maxlength="64"/></el-form-item><el-form-item label="绑定空间"><el-select v-model="form.spaceId" clearable :disabled="!!form.id"><el-option v-for="s in spaces" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="最多使用次数"><el-input-number v-model="form.maxUses" :min="1" :max="100000" :precision="0"/></el-form-item><el-form-item label="到期时间"><el-date-picker v-model="form.expiresAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" clearable/><span class="ps-muted">留空为永久有效</span></el-form-item><el-form-item label="初始对话 Token"><el-input-number v-model="form.initialLlmTokens" :min="0" :max="1000000000" :precision="0"/></el-form-item><el-form-item label="初始向量 Token"><el-input-number v-model="form.initialEmbeddingTokens" :min="0" :max="1000000000" :precision="0"/></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog><el-dialog v-model="generatedOpen" title="批量生成结果" width="700px"><el-button @click="copyInvites(generated,'codes')">复制全部邀请码</el-button><el-button @click="copyInvites(generated,'links')">复制全部注册入口</el-button><el-table :data="generated"><el-table-column prop="code" label="邀请码"/><el-table-column prop="expiresAt" label="有效期"/></el-table></el-dialog></div></template>
<script setup lang="ts">
import { onMounted,ref,shallowRef } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import { batchInvites,deleteInvite,listInvites,saveInvite } from '@/api/paismart/operations'
import {newKey} from '@/api/paismart/client'
import { listSpaces } from '@/api/paismart/spaces'
import type { Invite,Space } from '@/types/paismart'
import { errorText,usePage } from '../../composables/usePage'
import '../../common.css'
const {rows,total,query,loading,error,load}=usePage(listInvites),spaces=shallowRef<Space[]>([]),generated=shallowRef<Invite[]>([]),open=ref(false),generatedOpen=ref(false),saving=ref(false),batch=ref(false),count=ref(10),pageError=ref(''),formError=ref(''),form=ref<Partial<Invite>>({}),selected=shallowRef<Invite[]>([])
let requestKey=newKey(),lastFingerprint=''
function edit(row?:Invite,isBatch=false){requestKey=newKey();lastFingerprint='';form.value=row?{...row}:{code:'',maxUses:1,usedCount:0,expiresAt:'',enabled:true,initialLlmTokens:0,initialEmbeddingTokens:0};batch.value=isBatch;formError.value='';open.value=true}
async function save(){saving.value=true;formError.value='';try{const fingerprint=JSON.stringify({...form.value,count:batch.value?count.value:undefined});if(lastFingerprint&&lastFingerprint!==fingerprint)requestKey=newKey();lastFingerprint=fingerprint;if(batch.value){generated.value=(await batchInvites({...form.value,count:count.value},requestKey)).data;generatedOpen.value=true}else await saveInvite(form.value,requestKey);open.value=false;await load()}catch(e){formError.value=errorText(e)}finally{saving.value=false}}
async function toggle(row:Invite){try{await saveInvite({id:row.id,rowVersion:row.rowVersion,enabled:!row.enabled});await load()}catch(e){pageError.value=errorText(e)}}
async function remove(row:Invite){try{await ElMessageBox.confirm('删除邀请码后将拒绝新的资格领取，已领取的成员资格保持审计记录。', '删除邀请码',{type:'warning'});await deleteInvite(row);await load()}catch(e){if(e!=='cancel'&&e!=='close')pageError.value=errorText(e)}}
function registrationUrl(row:Invite){const url=new URL(import.meta.env.BASE_URL+'register',location.origin);url.searchParams.set('business','paismart');url.searchParams.set('invitationCode',row.code);return url.href}
async function copyInvites(items:Invite[],kind:'codes'|'links'|'words'){const text=items.map(row=>kind==='codes'?row.code:kind==='links'?registrationUrl(row):`欢迎使用知识库，邀请码：${row.code}。注册入口：${registrationUrl(row)}；有效期：${row.expiresAt||'永久有效'}`).join('\n');try{await navigator.clipboard.writeText(text);ElMessage.success('已复制')}catch{await ElMessageBox.alert(text,'复制内容')}}
async function registrationLink(row:Invite){await copyInvites([row],'links')}
async function bulk(deleting:boolean){try{await ElMessageBox.confirm(`${deleting?'删除':'停用'}所选 ${selected.value.length} 个邀请码？已领取资格不会被撤销。`,'批量操作',{type:'warning'});saving.value=true;pageError.value='';const failures:string[]=[];for(const row of selected.value){try{if(deleting)await deleteInvite(row);else await saveInvite({id:row.id,rowVersion:row.rowVersion,enabled:false})}catch(e){failures.push(`${row.code}：${errorText(e)}`)}}if(failures.length)pageError.value=failures.join('；');selected.value=[];await load()}catch(e){if(e!=='cancel'&&e!=='close')pageError.value=errorText(e)}finally{saving.value=false}}
onMounted(async()=>{void load();try{spaces.value=(await listSpaces()).rows.filter(s=>s.type==='ORGANIZATION'&&s.canManage)}catch(e){pageError.value=errorText(e)}})
</script>
